window.docContents[4].resolve({"/Basics/#Logical-Foundations--Basics___-Functional-Programming-in-Lean--Proof-by-Case-Analysis--Structural-Recursion-_LPAR_Optional_RPAR_":{"contents":"\n\nTo get a concrete sense of how termination checking works in Lean,\nfind a way to write a sensible recursive definition (of a simple\nfunction on numbers, say) that does actually terminate on all inputs,\nbut that Lean will reject because it cannot automatically prove\ntermination.\n\n","context":"Logical Foundations\u0009Basics: Functional Programming in Lean\u0009Proof by Case Analysis","header":"1.4.3. Structural Recursion (Optional)","id":"/Basics/#Logical-Foundations--Basics___-Functional-Programming-in-Lean--Proof-by-Case-Analysis--Structural-Recursion-_LPAR_Optional_RPAR_"}});